using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using ModelContextProtocol;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddHttpClient<WeatherTools>(client =>
    {
        client.BaseAddress = new Uri("https://api.weather.gov");
        client.DefaultRequestHeaders.UserAgent.ParseAdd("McpServer/1.0");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithTools<WeatherTools>();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor-injected HttpClient — registered via AddHttpClient<T>() in Program.cs.
    // The MCP SDK creates a new instance of this class per tool invocation,
    // resolving dependencies from the DI container each time.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the weather forecast for a US location by latitude and longitude.")]
    public async Task<string> GetForecast(
        [Description("Latitude (e.g. 39.7456)")] double latitude,
        [Description("Longitude (e.g. -97.0892)")] double longitude)
    {
        var pointUrl = $"/points/{latitude},{longitude}";
        var pointDoc = await GetJsonAsync(pointUrl);

        var forecastUrl = pointDoc.RootElement
            .GetProperty("properties")
            .GetProperty("forecast")
            .GetString()!;

        var forecastDoc = await GetJsonAsync(forecastUrl);
        var periods = forecastDoc.RootElement
            .GetProperty("properties")
            .GetProperty("periods");

        var lines = new List<string>();
        foreach (var p in periods.EnumerateArray().Take(5))
        {
            lines.Add($"{p.GetProperty("name").GetString()}: " +
                       $"{p.GetProperty("temperature").GetInt32()}°{p.GetProperty("temperatureUnit").GetString()} — " +
                       $"{p.GetProperty("shortForecast").GetString()}");
        }

        return string.Join("\n", lines);
    }

    [McpServerTool, Description("Get active weather alerts for a US state (two-letter code, e.g. 'CA').")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code")] string state)
    {
        var doc = await GetJsonAsync($"/alerts/active/area/{state}");
        var features = doc.RootElement.GetProperty("features");

        if (features.GetArrayLength() == 0)
            return $"No active alerts for {state}.";

        var lines = new List<string>();
        foreach (var f in features.EnumerateArray().Take(5))
        {
            var props = f.GetProperty("properties");
            lines.Add($"[{props.GetProperty("severity").GetString()}] " +
                       $"{props.GetProperty("headline").GetString()}");
        }

        return string.Join("\n", lines);
    }

    private async Task<JsonDocument> GetJsonAsync(string url)
    {
        using var response = await _httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();
        var stream = await response.Content.ReadAsStreamAsync();
        return await JsonDocument.ParseAsync(stream);
    }
}

